<section class="notice-detail-hero"><div class="container narrow"><a class="back-link" href="<?= url('notices') ?>">← All notices</a><div class="notice-detail-meta"><span><?= e($notice['category']) ?></span><time><?= format_date($notice['published_at']) ?></time><?php if($notice['is_pinned']):?><span>Pinned</span><?php endif?></div><h1><?= e($notice['title']) ?></h1><p><?= e($notice['excerpt']) ?></p></div></section><section class="section notice-detail-body"><div class="container narrow"><article><?= nl2br(e($notice['body'])) ?></article><?php if(!empty($notice['attachment_path'])):?><a class="button button-primary" href="<?= url($notice['attachment_path']) ?>" rel="noopener">Download attachment ↓</a><?php endif?><footer><span>Published by Netaji College of Pharmacy</span><a href="<?= url('contact') ?>">Ask about this notice →</a></footer></div></section><?php if($related):?><section class="section section-tint"><div class="container"><div class="section-heading"><div><span class="eyebrow">Continue reading</span><h2>Related notices</h2></div></div><div class="notice-cards"><?php foreach($related as $item):?><article><small><?= e($item['category']) ?> · <?= format_date($item['published_at']) ?></small><h3><?= e($item['title']) ?></h3><p><?= e($item['excerpt']) ?></p><a href="<?= url('notices/'.$item['slug']) ?>">Read notice →</a></article><?php endforeach?></div></div></section><?php endif?>
